 * Raised for any problem in the limiter file. `line` is 1-based; when it is
 * `null` the failure is the top-level usage error instead of a line error.
 */
export class LimiterError extends Error {
  constructor(message, line = null) {
    super(message)
    this.line = line
  }

  toDisplayString() {
    return this.line === null ? `error: ${this.message}` : `error: line ${this.line}: ${this.message}`
  }
}
"}

