/** A name, route prefix or event key: one or more of the allowed characters. */
const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/

/** An unsigned decimal integer with no sign and no leading zero unless it is `0`. */
const INT_RE = /^(0|[1-9][0-9]*)$/

export function isValidToken(str) {
  return TOKEN_RE.test(str)
}

/**
 * Parses an integer field, enforcing both the unsigned-decimal format and
 * the field's minimum value with a single combined error, as the spec asks.
 */
export function parseIntField(str, fieldName, least, line) {
  if (!INT_RE.test(str)) {
    throw new LimiterError(`${fieldName} must be an integer of at least ${least}`, line)
  }
  const value = BigInt(str)
  if (value < BigInt(least)) {
    throw new LimiterError(`${fieldName} must be an integer of at least ${least}`, line)
  }
  return value
}
"}

