{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-j68tDP/src/policies.js","content":"/**
 * A token bucket policy definition. Per-key state is tracked as
 * `tokens * per`, which stays an exact integer through every refill (adding
 * `refill * elapsed` units per advance) and every spend (subtracting `per`
 * units), so the fractional accumulation the spec requires never needs
 * rounding.
 */
export class BucketPolicy {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  advance(key, tick) {
    const full = this.capacity * this.per
    let state = this.states.get(key)
    if (state === undefined) {
      state = { scaled: full, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const scaled = state.scaled + this.refill * elapsed
      state.scaled = scaled > full ? full : scaled
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).scaled >= this.per
  }

  record(key) {
    this.states.get(key).scaled -= this.per
  }
}

/**
 * A sliding window policy definition. Per-key state is the ascending list of
 * remembered ticks; since ticks never go backwards across the file, expired
 * ticks are always at the front and can just be shifted off.
 */
export class WindowPolicy {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < state.ticks.length && state.ticks[drop] <= threshold) drop++
    if (drop > 0) state.ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.states.get(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).ticks.push(tick)
  }
}
"}

