/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { LimiterError } from './errors.js'
import { runLimiter } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    throw new LimiterError('usage: cli.js replay|summary')
  }

  const input = readStdin()
  const result = runLimiter(input)

  if (mode === 'replay') {
    let out = ''
    for (const line of result.replayLines) out += line + '\n'
    process.stdout.write(out)
  } else {
    let out = ''
    const sortedKeys = [...result.keyOrder].sort()
    for (const key of sortedKeys) {
      const counts = result.perKey.get(key)
      out += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
    }
    out += `total allowed=${result.totalAllowed} denied=${result.totalDenied}\n`
    process.stdout.write(out)
  }
}

try {
  main()
  process.exit(0)
} catch (err) {
  if (err instanceof LimiterError) {
    process.stderr.write(err.toDisplayString() + '\n')
    process.exit(2)
  }
  throw err
}
